#!/usr/bin/env python3
"""Run a command under a pty with an explicit window size, dumping raw output."""
import os, sys, pty, fcntl, termios, struct, select, signal, time

def main():
    rows = int(os.environ.get("PTY_ROWS", "24"))
    cols = int(os.environ.get("PTY_COLS", "80"))
    limit = float(os.environ.get("PTY_TIMEOUT", "600"))
    argv = sys.argv[1:]
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(argv[0], argv)
        os._exit(1)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    if os.environ.get("PTY_RAW", "1") == "1":
        # Disable output post-processing so \n is not rewritten to \r\n.
        attrs = termios.tcgetattr(fd)
        attrs[1] &= ~termios.OPOST
        attrs[3] &= ~(termios.ECHO | termios.ECHONL)
        termios.tcsetattr(fd, termios.TCSANOW, attrs)
    out = sys.stdout.buffer
    t0 = time.time()
    while True:
        if time.time() - t0 > limit:
            os.kill(pid, signal.SIGKILL)
            break
        r, _, _ = select.select([fd], [], [], 0.2)
        if fd in r:
            try:
                data = os.read(fd, 65536)
            except OSError:
                break
            if not data:
                break
            out.write(data)
        else:
            p, st = os.waitpid(pid, os.WNOHANG)
            if p == pid:
                # drain
                while True:
                    r, _, _ = select.select([fd], [], [], 0.1)
                    if fd not in r:
                        break
                    try:
                        data = os.read(fd, 65536)
                    except OSError:
                        break
                    if not data:
                        break
                    out.write(data)
                break
    out.flush()
    try:
        os.waitpid(pid, 0)
    except OSError:
        pass

main()
